14	test("categories and seasons are derived from TagSchema, so they can never drift", () => {
15	  expect(CATEGORIES).toEqual(TagSchema.shape.category.options);
16	  expect(SEASONS).toEqual(TagSchema.shape.seasons.element.options);
17	});
18	
19	test("formality labels cover 1..5 with a blank zero slot", () => {
20	  expect(FORMALITY_LABEL).toHaveLength(6);
21	  expect(FORMALITY_LABEL[0]).toBe("");
22	  expect(FORMALITY_LABEL[3]).toBe("Smart casual");
23	});
24	
25	test("patterns match what the tagger emits", () => {
26	  expect(PATTERNS).toEqual(["solid", "striped", "check", "print", "other"]);
27	});
28	
29	test("textures name knit structure, which material cannot express", () => {
30	  expect(TEXTURES).toEqual(expect.arrayContaining(["Ribbed", "Cable knit", "Waffle", "Brushed"]));
31	  // A texture is never a material and vice versa — overlapping the two lists
32	  // would make the tagger's choice ambiguous. "Other" is the deliberate
33	  // exception: both lists need their own escape hatch, and a structured-output
34	  // call with no way to say "none of these" returns a confident wrong answer.
35	  const overlap = (TEXTURES as readonly string[]).filter((t) =>
36	    (MATERIALS as readonly string[]).includes(t),
37	  );
38	  expect(overlap).toEqual(["Other"]);
39	});
40	
41	test("both vocabularies have an escape hatch", () => {
42	  // A required z.enum with no "Other" forces the model to mislabel rather than
43	  // admit it cannot tell. TEXTURES originally had none.
44	  expect(MATERIALS).toContain("Other");
45	  expect(TEXTURES).toContain("Other");
46	});
47	
48	test("the materials the generator's heat rule names all exist in the vocabulary", () => {
49	  // `HOT_MATERIALS` in lib/generator/rules.ts is matched against `material`.
50	  // Once material is a constrained enum, any term missing from this list
51	  // silently stops matching — which is how the rule half-broke before.
52	  // `quilted` is deliberately absent: it is a TEXTURE, and the heat rule must
53	  // read texture for it (see item-signals-in-generator, queue #12).
54	  for (const m of ["Fleece", "Shearling", "Down", "Tweed"]) expect(MATERIALS).toContain(m);
55	  expect(TEXTURES).toContain("Quilted");
56	});
