3	import { z } from "zod";
4	import { revalidatePath } from "next/cache";
5	import { redirect } from "next/navigation";
6	import { createClient } from "@/lib/supabase/server";
7	import { TagSchema } from "@/lib/ai/tagging-schema";
8	
9	const UpdateSchema = z.object({
10	  name: z.string().nullable(),
11	  brand: z.string().nullable(),
12	  category: TagSchema.shape.category,
13	  material: TagSchema.shape.material,
14	  formality: TagSchema.shape.formality,
15	  seasons: TagSchema.shape.seasons,
16	});
17	
18	export async function updateItem(itemId: string, input: unknown) {
19	  const data = UpdateSchema.parse(input);
20	  const supabase = await createClient();
21	  // RLS scopes this to the owner's rows; a foreign id simply matches 0 rows.
22	  const { error } = await supabase
23	    .from("items")
24	    .update({
25	      name: data.name,
26	      brand: data.brand,
27	      category: data.category,
28	      material: data.material,
29	      formality: data.formality,
30	      seasons: data.seasons,
31	    })
32	    .eq("id", itemId);
33	  if (error) throw error;
34	  revalidatePath("/closet");
35	  revalidatePath(`/closet/${itemId}`);
36	}
37	
38	export async function archiveItem(itemId: string) {
39	  const supabase = await createClient();
40	  const { error } = await supabase
41	    .from("items")
42	    .update({ archived: true })
43	    .eq("id", itemId);
44	  if (error) throw error;
45	  revalidatePath("/closet");
46	  redirect("/closet");
47	}
